package main

// newUI is a complete replacement for the original single-page dashboard.
const newUI = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Syncria — Sync control</title>
<style>
:root{color-scheme:light;--bg:#f4f8ff;--surface:#ffffff;--surface2:#edf5ff;--line:#d8e4f4;--ink:#092b54;--sub:#526c89;--accent:#0869f8;--accent2:#e6f3ff;--warn:#b56a10;--bad:#b23b42;font:14px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink)}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}a{color:inherit}main{max-width:1500px;margin:auto;display:grid;grid-template-columns:240px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;background:#101821;border-right:1px solid var(--line);padding:26px 15px;display:flex;flex-direction:column;gap:25px}.brand{display:flex;align-items:center;gap:12px;padding:0 13px;font-size:22px;font-weight:750;letter-spacing:-1px}.mark{background:var(--accent);color:#091b19;border-radius:12px;width:38px;height:38px;display:grid;place-items:center;font-size:25px}.tiny{font-size:11px;letter-spacing:1.1px;text-transform:uppercase;color:var(--sub);font-weight:750;padding:0 13px}.nav{display:grid;gap:4px}.nav button{display:flex;align-items:center;gap:11px;width:100%;padding:12px 14px;border:1px solid transparent;background:none;text-align:left;border-radius:10px;color:#aabccc}.nav button.active{background:var(--accent2);border-color:#255450;color:#b7f1e7}.nav button:hover{background:#1c2935}.sidebar-bottom{margin-top:auto;padding:0 12px;color:var(--sub);font-size:12px}.content{min-width:0;padding:32px clamp(18px,3.4vw,55px) 70px}.topline{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:27px}.eyebrow{color:var(--accent);font-size:11px;letter-spacing:1.6px;font-weight:800;text-transform:uppercase}.topline h1{font-size:30px;letter-spacing:-1px;margin:3px 0 0}.lead{color:var(--sub);margin:4px 0 24px}.pill{background:#19302f;color:#88d8c7;padding:6px 11px;border-radius:20px;border:1px solid #2b5852;font-size:12px}.logout{border:1px solid var(--line);background:none;border-radius:9px;color:var(--ink);padding:9px 13px}.view{display:none}.view.active{display:block}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:22px}.stat,.panel{background:var(--surface);border:1px solid var(--line);border-radius:14px}.stat{padding:21px}.stat strong{font-size:31px;font-weight:750;display:block;letter-spacing:-1px}.stat small{color:var(--sub)}.panel{padding:23px;margin-bottom:17px}.panel-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:15px}.panel h2{font-size:17px;letter-spacing:-.4px;margin:0}.panel p{color:var(--sub);margin:5px 0 15px}.split{display:grid;grid-template-columns:1.2fr 1fr;gap:17px}.primary,.secondary,.danger{border-radius:9px;padding:10px 15px;font-weight:700}.primary{background:var(--accent);color:#09201d;border:1px solid var(--accent)}.secondary{background:#1d2a38;border:1px solid #38485a;color:var(--ink)}.danger{background:#3b2428;border:1px solid #704047;color:#ffb8b8}.primary:hover{filter:brightness(1.1)}.row{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.entry{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--line);padding:16px 0}.entry:first-of-type{border-top:0}.entry strong{font-size:14px}.entry p{font-size:12px;margin:3px 0}.status{font-size:11px;color:#7ad7ad;border:1px solid #37634c;border-radius:20px;padding:3px 8px}.status.off{color:var(--warn);border-color:#62503b}.empty{padding:30px;text-align:center;border:1px dashed #3c4959;border-radius:11px;color:var(--sub)}.empty strong{display:block;color:var(--ink);margin-bottom:6px}.field{display:block;color:#c2d1df;font-size:12px;font-weight:650;margin:0 0 16px}.field input,.field select{display:block;background:#0e1720;border:1px solid #3b4b5c;border-radius:9px;width:100%;padding:12px;color:var(--ink);margin-top:6px;min-width:0}.field input:focus,.field select:focus{outline:2px solid var(--accent);outline-offset:2px}.muted{color:var(--sub);font-size:12px}.step{display:none}.step.active{display:block}.step-indicator{display:flex;gap:9px;margin-bottom:22px}.step-indicator span{background:#22303c;border:1px solid var(--line);border-radius:9px;padding:8px 12px;color:var(--sub);font-size:12px}.step-indicator span.active{background:var(--accent2);color:#a0e8db;border-color:#29655e}.selected{display:flex;align-items:center;justify-content:space-between;gap:15px;background:#101b26;border:1px solid #354958;border-radius:11px;padding:16px;margin-bottom:18px;min-width:0}.selected strong{display:block;overflow-wrap:anywhere}.picker{position:fixed;inset:0;background:#000b;z-index:30;display:none;align-items:center;justify-content:center;padding:18px}.picker.open{display:flex}.picker-box{background:#182330;border:1px solid #405165;border-radius:16px;width:min(720px,100%);max-height:86vh;display:flex;flex-direction:column;box-shadow:0 25px 90px #000a}.picker-head{padding:22px;border-bottom:1px solid var(--line)}.picker-head h2{margin:0}.picker-path{margin:8px 0 0;font-size:12px;color:var(--sub);overflow-wrap:anywhere}.picker-actions{padding:12px 22px;border-bottom:1px solid var(--line)}.folder-list{padding:9px 14px;min-height:180px;overflow:auto}.folder-row{display:block;width:100%;border:0;background:none;text-align:left;padding:13px 14px;color:var(--ink);border-radius:9px}.folder-row:hover{background:#293747}.picker-footer{border-top:1px solid var(--line);padding:16px 22px;display:flex;justify-content:space-between;gap:10px}.notice{padding:13px 17px;margin-bottom:20px;background:#152f32;border:1px solid #2c6666;border-radius:9px;color:#b3e6e1}.notice.bad{background:#362329;border-color:#774853;color:#ffc3c3}form.inline{display:inline}.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.hidden,[hidden]{display:none!important}.card-label{color:var(--sub);font-size:12px}code{color:#9fdfd4;overflow-wrap:anywhere}summary{cursor:pointer}.version{color:var(--sub);font-size:12px}@media(max-width:980px){main{grid-template-columns:1fr}.sidebar{position:static;height:auto;padding:13px;gap:12px}.sidebar-bottom,.tiny{display:none}.nav{display:flex;flex-wrap:wrap}.nav button{width:auto;padding:9px 12px}.brand{font-size:19px}.content{padding:22px 16px 60px}}@media(max-width:680px){.stats,.split,.settings-grid{grid-template-columns:1fr}.topline h1{font-size:25px}.panel{padding:17px}.entry{align-items:flex-start;flex-direction:column}.topline{align-items:flex-start}}
/* Syncria official identity: navy wordmark, electric blue and cyan symbol, white canvas. */
body{background:linear-gradient(150deg,#f7fbff 0%,#edf5ff 100%);color:#092b54}
.sidebar{background:#fff;border-right-color:#d6e4f4;box-shadow:3px 0 24px #10396609}
.brand{color:#052b55}.mark{background:linear-gradient(130deg,#0965ff 12%,#07c9eb 58%,#053ecb 100%);color:#fff;box-shadow:0 4px 13px #0965ff30}
.nav button{color:#355576}.nav button.active{color:#0757c7;background:#eaf4ff;border-color:#badcff}.nav button:hover{background:#edf5ff}
.eyebrow{color:#0869f8}.topline h1,.panel h2,.stat strong,.entry strong{color:#092d56}
.pill,.status{background:#ebf4ff;color:#1260c2;border:1px solid #b4d5ff}
.status.off{background:#fff6e8;color:#966113;border-color:#f0d2a0}
.stat,.panel{background:#fff;border:1px solid #d8e4f4;box-shadow:0 8px 28px #16487b09}
.primary{background:linear-gradient(110deg,#0869f8,#098fe9);color:#fff;border:1px solid #0872ef}
.primary:hover{filter:brightness(1.06)}.secondary{background:#f0f6ff;border:1px solid #cfdef2;color:#123d6e}
.logout{color:#123d6e;background:#fff;border-color:#d8e4f4}
.empty{color:#68819d;border-color:#d5e4f3}.empty strong{color:#092d56}
.field{color:#264a70}.field input,.field select{color:#092b54;background:#fff;border-color:#c7d9ec}
.selected{background:#f6faff;border-color:#d7e5f4}.card-label,.muted,.version,.lead{color:#597493}
.step-indicator span{background:#eff5fd;color:#5d7793;border-color:#d5e4f3}.step-indicator span.active{background:#e3f2ff;color:#0965d3;border-color:#a5d2fb}
.picker{background:#092b5470}.picker-box{background:#fff;border-color:#c9dbee;box-shadow:0 25px 90px #092b5440}.folder-row{color:#0c355e}.folder-row:hover{background:#eaf4ff}
.picker-head,.picker-actions,.picker-footer,.entry{border-color:#dce7f5}
.notice{color:#14559a;background:#eaf4ff;border-color:#bddaff}.notice.bad{color:#a82b44;background:#fff0f2;border-color:#e9b6c2}
code{color:#076bd3}
.danger{background:#fff0f2;border:1px solid #f1c2c9;color:#b32238}
</style></head><body>
<main><aside class="sidebar"><div class="brand"><img src="/assets/syncria-logo.svg" alt="Syncria" style="display:block;width:200px;max-width:100%;height:auto;object-fit:contain;object-position:left"></div><div><div class="tiny">Workspace</div><nav class="nav" aria-label="Main navigation">
<button class="active" type="button" data-view="overview">◫ &nbsp; Overview</button>
<button type="button" data-view="sync">⇄ &nbsp; Sync relationships</button>
<button type="button" data-view="storage">▤ &nbsp; Storage</button>
<button type="button" data-view="accounts">◎ &nbsp; Google accounts</button>
<button type="button" data-view="updates">↻ &nbsp; Updates</button>
<button type="button" data-view="settings">⚙ &nbsp; Settings</button>
</nav></div><div class="sidebar-bottom">Syncria <strong>v<span id="sidebarVersion">{{.Version}}</span></strong><p>Google Drive ↔ your storage</p></div></aside>
<div class="content"><div class="topline"><div><div class="eyebrow">Storage synchronization</div><h1 id="pageTitle">Overview</h1></div>{{if .Logged}}<form method="post" action="/action"><input type="hidden" name="action" value="logout"><button class="logout" type="submit">Sign out</button></form>{{end}}</div>
{{if .Message}}<div class="notice">{{.Message}}</div>{{end}}
{{if not .Configured}}<section class="panel" style="max-width:550px"><h2>Welcome to Syncria</h2><p>Create the administrator password to protect your dashboard.</p><form method="post" action="/action"><input type="hidden" name="action" value="setup"><label class="field">Administrator password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><button class="primary">Secure dashboard</button></form></section>
{{else if not .Logged}}<section class="panel" style="max-width:550px"><h2>Sign in</h2><p>Access your synchronization workspace.</p><form method="post" action="/action"><input type="hidden" name="action" value="login"><label class="field">Administrator password<input type="password" name="password" required autocomplete="current-password"></label><button class="primary">Sign in</button></form></section>
{{else}}
<section class="view active" id="view-overview"><p class="lead">Manage synchronization across your Google accounts, local folders and network storage.</p><div class="stats"><div class="stat"><small>Google accounts</small><strong>{{len .Accounts}}</strong><small>Connected</small></div><div class="stat"><small>Sync relationships</small><strong>{{len .Jobs}}</strong><small>Configured</small></div><div class="stat"><small>Network shares</small><strong>{{len .Shares}}</strong><small>Saved destinations</small></div></div>
<div class="split"><section class="panel"><div class="panel-head"><h2>Synchronization</h2><button class="primary" type="button" onclick="navigate('sync');startWizard()">+ New sync</button></div>{{range .Jobs}}<div class="entry"><div><strong>{{.Name}}</strong> {{if .Enabled}}<span class="status">Enabled</span>{{else}}<span class="status off">Paused</span>{{end}}<p>{{.Local}} · every {{.Interval}} minutes</p></div><button class="secondary" type="button" onclick="navigate('sync')">Manage</button></div>{{else}}<div class="empty"><strong>No sync relationships yet</strong>Choose a Drive folder and storage destination to begin.</div>{{end}}</section><section class="panel"><div class="panel-head"><h2>Connected storage</h2><button class="secondary" type="button" onclick="navigate('storage')">Manage</button></div>{{range .Shares}}<div class="entry"><div><strong>{{.Label}}</strong><p>{{.Protocol}} · {{.Server}}</p></div>{{if .Mounted}}<span class="status" data-share-mounted="{{.ID}}">Mounted</span>{{else}}<span class="status off" data-share-mounted="{{.ID}}">Disconnected</span>{{end}}</div>{{else}}<div class="empty"><strong>No managed network shares</strong>Local storage is still available.</div>{{end}}</section></div></section>
<section class="view" id="view-sync"><p class="lead">Create independent Drive-to-storage relationships. Nothing starts until you enable it.</p><section class="panel"><div class="panel-head"><h2>Sync relationships</h2><button type="button" class="primary" onclick="startWizard()">+ New sync</button></div>{{range .Jobs}}<div class="entry"><div><strong>{{.Name}}</strong> {{if .Enabled}}<span class="status" data-job-enabled="{{.ID}}">Enabled</span>{{else}}<span class="status off" data-job-enabled="{{.ID}}">Paused</span>{{end}}<p>{{.Local}} ↔ {{.RemoteID}}</p><p>Every {{.Interval}} min · <span data-job-run="{{.ID}}">{{if .LastRun.IsZero}}Never run{{else}}Last run {{.LastRun.Format "Jan 2, 2006 15:04"}}{{end}}</span> · <span data-job-summary="{{.ID}}">{{.LastSummary}}</span></p><p data-job-error="{{.ID}}" style="color:var(--bad)" {{if not .LastError}}hidden{{end}}>Error: {{.LastError}}</p></div><div class="row"><form class="inline" method="post" action="/action"><input type="hidden" name="action" value="run_job"><input type="hidden" name="id" value="{{.ID}}"><button class="secondary">Run</button></form><form class="inline" method="post" action="/action"><input type="hidden" name="action" value="toggle_job"><input type="hidden" name="id" value="{{.ID}}"><button class="secondary">{{if .Enabled}}Pause{{else}}Enable{{end}}</button></form><form class="inline" method="post" action="/action" onsubmit="return confirm('Remove mapping? Files will remain.')"><input type="hidden" name="action" value="delete_job"><input type="hidden" name="id" value="{{.ID}}"><button class="danger">Remove</button></form></div></div>{{else}}<div class="empty"><strong>No sync relationships</strong>Use New sync to create your first relationship.</div>{{end}}</section>
<section id="wizard" class="panel hidden"><div class="panel-head"><h2>New sync relationship</h2><button type="button" class="secondary" onclick="document.getElementById('wizard').classList.add('hidden')">Close</button></div><div class="step-indicator"><span id="stepMarker1" class="active">1 · Google Drive</span><span id="stepMarker2">2 · Storage & schedule</span></div>
<form method="post" action="/action" id="syncWizard"><input type="hidden" name="action" value="add_job"><div class="step active" id="wizard1"><label class="field">Relationship name<input name="name" placeholder="Family backups" required></label><label class="field">Google account<select name="account" id="syncAccount" required onchange="resetDrive()">{{range .Accounts}}<option value="{{.ID}}">{{.Email}}</option>{{end}}</select></label><div class="selected"><div><span class="card-label">Google Drive source</span><strong id="selectedDriveLabel">Entire My Drive</strong></div><button class="secondary" type="button" onclick="openPicker('drive')">Browse folders</button></div><input type="hidden" name="remote" id="remoteValue" value="root"><button class="primary" type="button" onclick="wizardNext()">Continue →</button></div>
<div class="step" id="wizard2"><div class="selected"><div><span class="card-label">Local or network destination</span><strong id="selectedLocalLabel">Choose a destination</strong></div><button class="secondary" type="button" onclick="openPicker('local')">Browse storage</button></div><input type="hidden" name="local" id="localValue" required><label class="field">Sync frequency<select name="interval"><option value="5">Every 5 minutes</option><option value="15">Every 15 minutes</option><option value="30">Every 30 minutes</option><option value="60">Every hour</option><option value="360">Every 6 hours</option><option value="1440">Daily</option></select></label><p class="muted">New relationships are created paused. Review the source and destination before enabling synchronization.</p><div class="row"><button type="button" class="secondary" onclick="wizardBack()">← Back</button><button class="primary" {{if not .Accounts}}disabled{{end}}>Create relationship</button></div></div></form></section></section>
<section class="view" id="view-storage"><p class="lead">Choose local destinations or connect NFS and SMB network storage.</p><div class="row" style="margin-bottom:19px"><button class="primary" type="button" onclick="toggleConnection()">+ Add network connection</button><button class="secondary" type="button" onclick="openPicker('local')">Browse available folders</button></div><section class="panel hidden" id="connectionPanel"><div class="panel-head"><h2>Connect network storage</h2><button class="secondary" type="button" onclick="toggleConnection(false)">Close</button></div><p>Linux mounting requires opt-in kernel mount permissions. Syncria reports mount errors rather than silently accepting failed connections.</p><form method="post" action="/api/shares/action"><input type="hidden" name="operation" value="connect"><div class="settings-grid"><label class="field">Connection name<input name="label" placeholder="Media NAS" required maxlength="128"></label><label class="field">Protocol<select name="protocol" id="shareProtocol" onchange="protocolChanged()"><option value="smb">SMB / Windows</option><option value="nfs">NFS / Linux</option></select></label><label class="field">Hostname or IP<input name="server" id="shareServer" placeholder="192.168.0.20" required oninput="queueShareDiscovery()"></label><label class="field"><span id="sharePathTitle">SMB share name</span><input name="export" id="sharePath" placeholder="Shared" list="discoveredShares" required><datalist id="discoveredShares"></datalist><span id="shareDiscoveryStatus" class="muted" aria-live="polite"></span><div id="shareDiscoveryList" class="row" style="flex-wrap:wrap;margin-top:8px" aria-label="Discovered network shares"></div></label></div><div class="settings-grid" id="smbFields"><label class="field">SMB username<input name="username" autocomplete="username"></label><label class="field">SMB password<input type="password" name="password" autocomplete="new-password"></label></div><button class="primary">Connect share</button></form></section>
<section class="panel"><h2>Network shares</h2>{{range .Shares}}<div class="entry"><div><strong>{{.Label}}</strong> {{if .Mounted}}<span class="status" data-share-mounted="{{.ID}}">Mounted</span>{{else}}<span class="status off" data-share-mounted="{{.ID}}">Disconnected</span>{{end}}<p>{{.Protocol}} · {{.Server}} / {{.Export}}</p><p>{{.Local}}</p></div><div class="row"><form class="inline" method="post" action="/api/shares/action"><input type="hidden" name="operation" value="reconnect"><input type="hidden" name="id" value="{{.ID}}"><button class="secondary">Reconnect</button></form><form class="inline" method="post" action="/api/shares/action" onsubmit="return confirm('Disconnect network storage?')"><input type="hidden" name="operation" value="disconnect"><input type="hidden" name="id" value="{{.ID}}"><button class="danger">Disconnect</button></form></div></div>{{else}}<div class="empty"><strong>No managed shares</strong>Connect a network share above or browse an existing local mount.</div>{{end}}</section></section>
<section class="view" id="view-accounts"><p class="lead">Connect multiple Google accounts, then choose folders independently for each sync relationship.</p><section class="panel"><div class="panel-head"><h2>Google accounts</h2><a class="primary" style="text-decoration:none" href="/oauth/start">+ Connect Google account</a></div>{{range .Accounts}}<div class="entry"><div><strong>{{.Email}}</strong><p>Authorized with Google Drive</p></div><div class="row"><span class="status">Connected</span><form method="post" action="/action" class="inline" onsubmit="return confirm('Disconnect account?')"><input type="hidden" name="action" value="remove_account"><input type="hidden" name="id" value="{{.ID}}"><button class="danger">Disconnect</button></form></div></div>{{else}}<div class="empty"><strong>No accounts connected</strong>Connect a Google account to start.</div>{{end}}</section></section>
<section class="view" id="view-updates"><p class="lead">Install verified versioned releases without losing your persistent configuration.</p><section class="panel"><div class="panel-head"><h2>Software updates</h2><span class="pill">Installed: <span id="installedVersion">{{.Version}}</span></span></div><div class="selected"><div><span class="card-label">Latest GitHub version tag</span><strong id="latestVersion">Checking releases…</strong><span class="muted" id="updateMessage"></span></div><button class="secondary" type="button" onclick="checkUpdate()">Check again</button></div><div class="row"><form method="post" action="/action" onsubmit="return confirm('Install latest verified release and restart Syncria?')"><input type="hidden" name="action" value="update_install"><button id="installUpdateButton" class="primary" disabled>Install latest</button></form><form method="post" action="/action" onsubmit="return confirm('Rollback to previous version?')"><input type="hidden" name="action" value="update_rollback"><button class="secondary">Rollback</button></form></div><p style="margin-top:18px">Updates are blocked while synchronization is active. Versions are discovered from GitHub tags. Installation is enabled when verified binaries and checksums are published.</p></section><section class="panel"><h2>Manual update</h2><p class="muted">Upload the Syncria executable and SHA256SUMS from the same GitHub release. The server verifies the binary checksum before installing. No GitHub API access is required.</p><form action="/api/update/manual" method="post" enctype="multipart/form-data" onsubmit="return confirm('Verify uploaded release files, install, and restart Syncria?')"><label class="field">Syncria application binary<input type="file" name="binary" required></label><label class="field">SHA256SUMS<input type="file" name="checksums" required></label><button class="primary" type="submit">Verify and install uploaded update</button></form></section></section>
<section class="view" id="view-settings"><p class="lead">Application configuration and account authorization.</p><section class="panel"><h2>Google OAuth</h2><p>Set up a Google Cloud OAuth web application, enable Drive API and register this callback URI:</p><div class="selected"><code>{{.Callback}}</code></div><form method="post" action="/action"><input type="hidden" name="action" value="oauth_settings"><label class="field">Client ID<input name="client_id" value="{{.ClientID}}" required></label><label class="field">Client secret<input name="client_secret" type="password" placeholder="Leave blank to keep existing secret"></label><label class="field">Public dashboard URL<input name="base_url" value="{{.BaseURL}}" required></label><button class="primary">Save OAuth settings</button></form></section></section>
{{end}}</div></main>
<div class="picker" id="picker" role="dialog" aria-modal="true" aria-labelledby="pickerTitle"><div class="picker-box"><div class="picker-head"><div class="panel-head" style="margin:0"><h2 id="pickerTitle">Select folder</h2><button class="secondary" type="button" onclick="closePicker()">✕ Close</button></div><div id="pickerPath" class="picker-path">Loading…</div></div><div class="row picker-actions"><button class="secondary" type="button" id="pickerUp" onclick="pickerUp()">← Back</button><button class="secondary" type="button" id="pickerNew" onclick="createFolder()">+ New folder</button></div><div id="folderList" class="folder-list" aria-live="polite"></div><div class="picker-footer"><small id="pickerStatus" class="muted">Choose a folder.</small><button class="primary" type="button" id="pickerSelect" onclick="selectFolder()">Select folder</button></div></div></div>
<script>
const $=id=>document.getElementById(id);
let currentView='overview',pickerType='',folder='',parent='',folderName='',pickSeq=0;
function navigate(view){if(!$('view-'+view))return;currentView=view;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id==='view-'+view));document.querySelectorAll('.nav button').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('pageTitle').textContent=({'overview':'Overview','sync':'Sync relationships','storage':'Storage connections','accounts':'Google accounts','updates':'Updates','settings':'Settings'})[view]||view;history.replaceState(null,'','#'+view);if(view==='updates')checkUpdate();}
document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
function startWizard(){navigate('sync');$('wizard').classList.remove('hidden');wizardBack();$('wizard').scrollIntoView({behavior:'smooth',block:'start'});}
function wizardNext(){let f=$('syncWizard');if(!f.querySelector('[name=name]').reportValidity()||!f.querySelector('[name=account]').reportValidity())return;$('wizard1').classList.remove('active');$('wizard2').classList.add('active');$('stepMarker1').classList.remove('active');$('stepMarker2').classList.add('active');}
function wizardBack(){$('wizard1').classList.add('active');$('wizard2').classList.remove('active');$('stepMarker1').classList.add('active');$('stepMarker2').classList.remove('active');}
function resetDrive(){$('remoteValue').value='root';$('selectedDriveLabel').textContent='Entire My Drive';}
function toggleConnection(force){$('connectionPanel').classList.toggle('hidden',force===undefined?!$('connectionPanel').classList.contains('hidden'):!force);if(!$('connectionPanel').classList.contains('hidden'))$('connectionPanel').scrollIntoView({behavior:'smooth'});}
function protocolChanged(){shareDiscoverySequence++;clearTimeout(shareDiscoveryTimer);$('shareDiscoveryStatus').textContent='';$('discoveredShares').replaceChildren();$('shareDiscoveryList').replaceChildren();let nfs=$('shareProtocol').value==='nfs';$('smbFields').classList.toggle('hidden',nfs);$('sharePathTitle').textContent=nfs?'NFS export path':'SMB share name';$('sharePath').placeholder=nfs?'/volume1/shared':'Shared';}
let shareDiscoveryTimer=0,shareDiscoverySequence=0;
function queueShareDiscovery(){
 clearTimeout(shareDiscoveryTimer);
 const host=$('shareServer').value.trim();
 $('discoveredShares').replaceChildren();
 $('shareDiscoveryList').replaceChildren();
 $('shareDiscoveryStatus').textContent='';
 if($('shareProtocol').value!=='smb'||!host)return;
 shareDiscoveryTimer=setTimeout(discoverShares,450);
}
async function discoverShares(){
 const host=$('shareServer').value.trim(),sequence=++shareDiscoverySequence;
 if(!host||$('shareProtocol').value!=='smb')return;
 $('shareDiscoveryStatus').textContent='Discovering SMB shares…';
 try{
  const res=await fetch('/api/shares/discover?server='+encodeURIComponent(host),{credentials:'same-origin',cache:'no-store'});
  const data=await res.json();
  if(sequence!==shareDiscoverySequence||$('shareServer').value.trim()!==host)return;
  if(!res.ok)throw Error(data.error||'Discovery failed');
  $('discoveredShares').replaceChildren();
  $('shareDiscoveryList').replaceChildren();
  for(const name of data.shares||[]){const option=document.createElement('option');option.value=name;$('discoveredShares').appendChild(option);const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=name;button.addEventListener('click',()=>{$('sharePath').value=name;$('shareDiscoveryStatus').textContent='Selected '+name;});$('shareDiscoveryList').appendChild(button);}
  $('shareDiscoveryStatus').textContent=(data.shares||[]).length?data.shares.length+' shares discovered. Select a share or enter its name.':'No browseable shares were advertised. You can enter a known share manually.';
 }catch(e){if(sequence!==shareDiscoverySequence)return;$('shareDiscoveryStatus').textContent=e.message+'. You can enter a known share manually.';}
}
async function checkUpdate(){
 if(!$('latestVersion'))return;
 $('latestVersion').textContent='Checking GitHub tags…';
 $('updateMessage').textContent='';
 if($('installUpdateButton'))$('installUpdateButton').disabled=true;
 try{
  const res=await fetch('/api/update/status',{cache:'no-store',credentials:'same-origin'});
  if(!res.ok)throw Error('HTTP '+res.status);
  const obj=await res.json();
  if(obj.error)throw Error(obj.error);
  $('latestVersion').textContent=obj.latest||'No tag found';
  $('updateMessage').textContent=obj.pending?' · '+(obj.message||'Waiting for installable binaries'):obj.available?' · Ready to install':' · You are up to date';
  if($('installUpdateButton'))$('installUpdateButton').disabled=!obj.available;
 }catch(e){$('latestVersion').textContent='Unable to check tags';$('updateMessage').textContent=e.message;}
}
function openPicker(type){pickerType=type;folder='';parent='';folderName='';$('picker').classList.add('open');$('pickerTitle').textContent=type==='drive'?'Browse Google Drive':'Choose storage folder';$('pickerNew').classList.toggle('hidden',type==='drive');loadFolder(type==='drive'?'root':'');}
function closePicker(){pickSeq++;$('picker').classList.remove('open');}
async function loadFolder(path,label){let seq=++pickSeq;let drive=pickerType==='drive',account=$('syncAccount');$('pickerStatus').textContent='Loading folders…';$('pickerSelect').disabled=true;$('folderList').replaceChildren();let endpoint=drive?'/api/browse/drive?account='+encodeURIComponent(account?account.value:'')+'&parent='+encodeURIComponent(path||'root'):'/api/browse/local?path='+encodeURIComponent(path);try{let resp=await fetch(endpoint,{cache:'no-store'});if(!resp.ok)throw Error((await resp.text()).trim());let data=await resp.json();if(seq!==pickSeq)return;folder=data.path;parent=data.parent||'';if(label)folderName=label;else if(drive&&folder==='root')folderName='Entire My Drive';else if(!drive)folderName=folder;$('pickerPath').textContent=drive?('My Drive / '+folderName):folder;$('pickerUp').disabled=!parent;$('pickerSelect').disabled=false;data.entries.forEach(item=>{let b=document.createElement('button');b.type='button';b.className='folder-row';b.textContent='📁   '+item.name;b.addEventListener('click',()=>loadFolder(item.id,item.name));$('folderList').appendChild(b)});$('pickerStatus').textContent=data.message||(data.entries.length?data.entries.length+' folders · Select current folder or open another.':'No subfolders · Select this folder.');}catch(e){if(seq!==pickSeq)return;$('pickerStatus').textContent='Unable to load folders: '+e.message;}}
function pickerUp(){if(parent)loadFolder(parent,parent==='root'?'Entire My Drive':undefined);}
function selectFolder(){if(!folder)return;if(pickerType==='drive'){$('remoteValue').value=folder;$('selectedDriveLabel').textContent=folderName||folder;}else{$('localValue').value=folder;$('selectedLocalLabel').textContent=folder;}closePicker();}
async function createFolder(){if(pickerType!=='local'||!folder)return;let name=prompt('New folder name');if(name===null)return;name=name.trim();if(!name)return;let p=new URLSearchParams({parent:folder,name});try{let res=await fetch('/api/browse/local/create',{method:'POST',body:p});if(!res.ok)throw Error((await res.text()).trim());await loadFolder(folder);}catch(e){$('pickerStatus').textContent='Could not create folder: '+e.message;}}
// Never navigate away from an active UI session in response to background polling.
// The Updates screen checks the installed version on demand. The server restart
// during an explicit installation is handled by the existing update workflow.
// Poll only small status fields; never replace forms, panels, or the document.
let dashboardPollBusy=false;
async function refreshDashboardStatus(){
 if(document.hidden||dashboardPollBusy||!$('view-overview'))return;
 dashboardPollBusy=true;
 try{
  const res=await fetch('/api/dashboard/status',{cache:'no-store',credentials:'same-origin'});
  if(!res.ok)return;
  const data=await res.json();
  if($('installedVersion')&&data.current)$('installedVersion').textContent=data.current;
  if($('sidebarVersion')&&data.current)$('sidebarVersion').textContent=data.current;
  for(const job of data.jobs||[]){
   for(const el of document.querySelectorAll('[data-job-enabled]')){
    if(el.dataset.jobEnabled!==job.id)continue;
    el.textContent=job.running?'Running':job.enabled?'Enabled':'Paused';
    el.classList.toggle('off',!job.enabled&&!job.running);
   }
   const run=document.querySelector('[data-job-run="'+CSS.escape(job.id)+'"]');
   if(run)run.textContent=job.last_run==='Never run'?'Never run':'Last run '+job.last_run;
   const summary=document.querySelector('[data-job-summary="'+CSS.escape(job.id)+'"]');
   if(summary)summary.textContent=job.summary||'';
   const error=document.querySelector('[data-job-error="'+CSS.escape(job.id)+'"]');
   if(error){error.hidden=!job.error;error.textContent=job.error?'Error: '+job.error:'';}
  }
  for(const share of data.shares||[]){
   for(const el of document.querySelectorAll('[data-share-mounted]')){
    if(el.dataset.shareMounted!==share.id)continue;
    el.textContent=share.mounted?'Mounted':'Disconnected';
    el.classList.toggle('off',!share.mounted);
   }
  }
 }catch(_e){/* Keep the current UI intact through temporary connection loss. */}
 finally{dashboardPollBusy=false;}
}
setInterval(refreshDashboardStatus,15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDashboardStatus()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePicker()});if(location.hash){let page=location.hash.slice(1);if($('view-'+page))navigate(page)}
</script></body></html>`
